PortalBuilderForm = {
    init: async function (app, container) {
        if (!app) { app = session.app; }
        if (!container) { container = $(".component[name=PortalBuilderForm]"); }

        var appCreationForms = (await api.get("ContentManagement/Component?$filter=AppId eq " + app.Id + " and Category eq 'App Creation'")).value;
        $("[name=AppType]", container).kendoDropDownList({
            optionLabel: "[resource_displayname[CreationFormSelect]]",
            dataTextField: "Name",
            dataValueField: "Name",
            change: function (e) {
                var value = this.value();
                loadComponent($("[name=AppCreationForm]", container), value, function (componentObject) {
                    componentObject.init(app, $("[name=AppCreationForm]", container));
                });
            },
            dataSource: {
                data: appCreationForms
            }
        });
    }
}
